export type DependencyType = 'agentUsage' | 'credentialId' | 'dataTableId' | 'errorWorkflow' | 'errorWorkflowParent' | 'workflowCall' | 'workflowParent';
export type DependencyResourceType = 'workflow' | 'credential' | 'dataTable';
export interface ResolvedDependency {
    type: DependencyType;
    id: string;
    name: string;
    projectId?: string;
    unavailable?: boolean;
}
export interface ResolvedDependenciesResult {
    dependencies: ResolvedDependency[];
    inaccessibleCount: number;
}
export type DependenciesBatchResponse = Record<string, ResolvedDependenciesResult>;
